// Throwaway: DuckDB's own Arrow output for a page of events, versus reading rows one by one and writing JSON.
use arrow_ipc::writer::StreamWriter;
use duckdb::arrow::array::{RecordBatch, StructArray};
use duckdb::Connection;
use serde_json::{json, Map, Value};
use std::time::Instant;
fn time<T>(mut f: impl FnMut() -> T) -> f64 { let mut v = vec![]; let t0 = Instant::now(); let mut n = 0; while n < 15 || (t0.elapsed().as_millis() < 500 && n < 300) { let t = Instant::now(); std::hint::black_box(f()); v.push(t.elapsed().as_secs_f64() * 1000.0); n += 1; } v.sort_by(|a, b| a.partial_cmp(b).unwrap()); v[v.len() / 2] }
fn main() { let dir = std::env::args().nth(1).unwrap(); let c = Connection::open_in_memory().unwrap();
  c.execute_batch("CREATE TABLE events AS SELECT i::UBIGINT AS id, CASE WHEN i%50=0 THEN NULL ELSE TIMESTAMP '2026-11-01' + INTERVAL (i*37) MILLISECOND END AS ts, (['Verbose','Debug','Information','Warning','Error','Fatal'])[1+(hash(i)%6)::INT] AS level, 'connection timeout worker '||hash(i)::VARCHAR||' request session cache miss flush commit rollback handler dispatch queue peer socket certificate expired gateway' AS message, CASE WHEN i%10<6 THEN 'template {a} worker {b} request session cache miss' ELSE NULL END AS template, CASE WHEN i%20=0 THEN repeat('at frame ', 180) ELSE NULL END AS exception, (i%12)::UINTEGER AS source, (i*3+1)::UINTEGER AS line, (i*411)::UBIGINT AS byte_offset, map(['connectionId','workerName','latencyMs','requestPath','sessionId','cacheName','queueMs','peerPath'], [hash(i)::VARCHAR, 'worker '||(i%9)::VARCHAR, (i%1000)::VARCHAR, '/api/v1/items/'||(i%77)::VARCHAR, hash(i+1)::VARCHAR, 'cache-a', (i%50)::VARCHAR, '/peer/'||(i%5)::VARCHAR]) AS extra FROM range(100000) t(i);").unwrap();
  for n in [200usize, 5000] { let sql = format!("SELECT * FROM events WHERE id >= 50000 ORDER BY id LIMIT {n}");
    let mut last: Vec<u8> = vec![]; let mut types = String::new();
    let arrow = time(|| { let mut st = c.prepare(&sql).unwrap(); let _ = st.stream_arrow([]).unwrap(); let mut out = vec![]; let mut w: Option<StreamWriter<&mut Vec<u8>>> = None; let mut bs = vec![]; while let Some(chunk) = st.step().unwrap() { bs.push(RecordBatch::from(&chunk as &StructArray)); } for b in &bs { if w.is_none() { w = Some(StreamWriter::try_new(&mut out, b.schema_ref()).unwrap()); } w.as_mut().unwrap().write(b).unwrap(); } if let Some(mut x) = w { x.finish().unwrap(); } if types.is_empty() { types = bs[0].schema().fields().iter().map(|f| format!("{}:{}", f.name(), f.data_type())).collect::<Vec<_>>().join(", "); println!("chunks {} types {types}", bs.len()); } drop(bs); last = out; });
    std::fs::write(format!("{dir}/duck{n}.arrow"), &last).unwrap();
    let jsn = time(|| { let mut st = c.prepare(&sql).unwrap(); let rows: Vec<Value> = st.query_map([], |r| { let mut m = Map::new(); m.insert("id".into(), json!(r.get::<_, u64>(0)?)); m.insert("level".into(), json!(r.get::<_, String>(2)?)); m.insert("message".into(), json!(r.get::<_, String>(3)?)); m.insert("template".into(), json!(r.get::<_, Option<String>>(4)?)); m.insert("exception".into(), json!(r.get::<_, Option<String>>(5)?)); m.insert("source".into(), json!(r.get::<_, u32>(6)?)); m.insert("line".into(), json!(r.get::<_, u32>(7)?)); m.insert("byteOffset".into(), json!(r.get::<_, u64>(8)?)); Ok(Value::Object(m)) }).unwrap().map(|x| x.unwrap()).collect(); serde_json::to_vec(&rows).unwrap() });
    println!("rows {n}: arrow query+write {arrow:.3} ms, {} B; row loop (no map column)+JSON {jsn:.3} ms", last.len()); } }
